import { exec } from 'child_process';
import util from 'util';
import fs from 'fs/promises';
import path from 'path';
import pdf from 'pdf-extraction';
import { completion, LLAMA_3_2_1B_INST_Q4_0, loadModel, unloadModel, close } from "@qvac/sdk";

const execPromise = util.promisify(exec);

export async function POST(request) {
    try {
        const data = await request.formData();
        const file = data.get('file');

        // 1. Guardar archivo temporal para el script de Python
        const buffer = Buffer.from(await file.arrayBuffer());
        const tempPdfPath = path.join(process.cwd(), 'temp_factura.pdf');
        const outDir = path.join(process.cwd(), 'output');
        await fs.writeFile(tempPdfPath, buffer);

        // 2. Extraer solo el inicio del texto para QVAC (ahorro extremo de memoria)
        const pdfData = await pdf(buffer);
        const primeraPagina = pdfData.text.substring(0, 1500);

        console.log("[SYS] Iniciando procesamiento paralelo (Python + QVAC)...");

        // 3. Ejecución Paralela
        const [pythonResult, qvacResult] = await Promise.all([
            // Hilo 1: Fuerza Bruta Geométrica (Python)
            execPromise(`python3 procesar_factura.py ${tempPdfPath} ${outDir}`),

            // Hilo 2: Inteligencia Soberana (QVAC)
            (async () => {
                const modelId = await loadModel({ modelSrc: LLAMA_3_2_1B_INST_Q4_0, modelType: "llm" });
                const history = [
                    { role: "system", content: "Extrae metadatos en JSON estricto. Usa 'Desconocido' si falta algo." },
                    { role: "user", content: `Devuelve JSON con: "remitente", "destinatario", "incoterm".\n\nTEXTO:\n${primeraPagina}` }
                ];

                const result = completion({ modelId, history, stream: true });
                let textoAcumulado = "";
                for await (const token of result.tokenStream) textoAcumulado += token;

                await unloadModel({ modelId });

                const jsonMatch = textoAcumulado.match(/\{[\s\S]*\}/);
                return jsonMatch ? JSON.parse(jsonMatch[0]) : { error: "No se pudo extraer metadatos" };
            })()
        ]);

        await close();

        // 4. Consolidar Resultados
        return Response.json({
            status: "success",
            metadatos_factura: qvacResult,
            tabla_procesada: true,
            mensaje_python: "El CSV detallado fue generado en la carpeta output."
        });

    } catch (error) {
        console.error("[ERROR HÍBRIDO]", error);
        try { await close(); } catch (e) { }
        return Response.json({ error: "Fallo en el motor híbrido" }, { status: 500 });
    }
}